import React, { useEffect, useRef, useState } from 'react';
import { Badge, Spinner, Modal, Button } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { filterFormContainer, petrolAllowanceContainer } from './formFieldData';
import Table from '../../components/Table';
import { dateConversion, findArrObj, removeNullKeyFromObj, showMessage } from '../../utils/AllFunction';
import { createPetrolAllowanceRequest, getPetrolAllowanceRequest, getStaffRequest, resetCreatePetrolAllowance, resetGetPetrolAllowance, resetUpdatePetrolAllowance, resetGetStaff, updatePetrolAllowanceRequest, getPetrolAllowanceReportRequest, resetGetPetrolAllowanceReport, getBranchRequest, getDepartmentRequest, resetGetBranch, resetGetDepartment, approvePetrolAllowanceImageRequest, resetApprovePetrolAllowanceImage, disapprovePetrolAllowanceImageFailure, disapprovePetrolAllowanceImageSuccess, disapprovePetrolAllowanceImageRequest, resetDisapprovePetrolAllowanceImage } from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks';
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';
import moment from 'moment';
import { createUploadImagesRequest, resetCreateUploadImages } from '../../redux/uploads/actions';
import { useNavigate } from 'react-router-dom';
import { baseURL } from '../../api/ApiConfig';
import ImageNotFound from '../../assets/images/image-not-found.webp';
import noProfile from '../../assets/images/noprofile_images.jpg';

let isEdit = false;

function Index() {

    usePageTitle({
        title: 'Allowance',
        breadCrumbItems: [
            {
                path: '/allowance/petrol-allowance',
                label: 'Allowance',
            },
            {
                path: '/allowance/petrol-allowance',
                label: 'Petrol Allowance',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', "Petrol Allowance");
    const accessIds = (pageAccessData?.[0]?.access || '')?.split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const navigate = useNavigate();
    const {
        getPetrolAllowanceSuccess,
        getPetrolAllowanceList,
        getPetrolAllowanceFailure,
        createPetrolAllowanceSuccess,
        createPetrolAllowanceData,
        createPetrolAllowanceFailure,
        updatePetrolAllowanceSuccess,
        updatePetrolAllowanceData,
        updatePetrolAllowanceFailure,
        approvePetrolAllowanceImageSuccess,
        approvePetrolAllowanceImageFailure,
        disapprovePetrolAllowanceImageFailure,
        disapprovePetrolAllowanceImageSuccess,
        getPetrolAllowanceReportSuccess,
        getPetrolAllowanceReportData,
        getPetrolAllowanceReportFailure,
        getBranchSuccess,
        getBranchList,
        getBranchFailure,
        getDepartmentSuccess,
        getDepartmentList,
        getDepartmentFailure,
        createUploadImagesSuccess,
        createUploadImagesFailure,
        errorMessage
    } = appSelector((state) => ({
        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,

        getPetrolAllowanceSuccess: state.petrolAllowanceReducer.getPetrolAllowanceSuccess,
        getPetrolAllowanceList: state.petrolAllowanceReducer.getPetrolAllowanceList,
        getPetrolAllowanceFailure: state.petrolAllowanceReducer.getPetrolAllowanceFailure,

        getPetrolAllowanceReportSuccess: state.petrolAllowanceReducer.getPetrolAllowanceReportSuccess,
        getPetrolAllowanceReportData: state.petrolAllowanceReducer.getPetrolAllowanceReportData,
        getPetrolAllowanceReportFailure: state.petrolAllowanceReducer.getPetrolAllowanceReportFailure,

        createPetrolAllowanceSuccess: state.petrolAllowanceReducer.createPetrolAllowanceSuccess,
        createPetrolAllowanceData: state.petrolAllowanceReducer.createPetrolAllowanceData,
        createPetrolAllowanceFailure: state.petrolAllowanceReducer.createPetrolAllowanceFailure,

        updatePetrolAllowanceSuccess: state.petrolAllowanceReducer.updatePetrolAllowanceSuccess,
        updatePetrolAllowanceData: state.petrolAllowanceReducer.updatePetrolAllowanceData,
        updatePetrolAllowanceFailure: state.petrolAllowanceReducer.updatePetrolAllowanceFailure,

        createUploadImagesSuccess: state.uploadImagesReducer.createUploadImagesSuccess,
        createUploadImagesFailure: state.uploadImagesReducer.createUploadImagesFailure,

        approvePetrolAllowanceImageSuccess: state.petrolAllowanceReducer.approvePetrolAllowanceImageSuccess,
        approvePetrolAllowanceImageFailure: state.petrolAllowanceReducer.approvePetrolAllowanceImageFailure,
        disapprovePetrolAllowanceImageSuccess: state.petrolAllowanceReducer.disapprovePetrolAllowanceImageSuccess,
        disapprovePetrolAllowanceImageFailure: state.petrolAllowanceReducer.disapprovePetrolAllowanceImageFailure,

        errorMessage: state.petrolAllowanceReducer.errorMessage,
    }));

    const [showImageDialog, setShowImageDialog] = useState(false);
    const [currentImageUrl, setCurrentImageUrl] = useState('');
    const [currentPetrolId, setCurrentPetrolId] = useState(null);
    const [currentRowIndex, setCurrentRowIndex] = useState(null);
    const [imageLoading, setImageLoading] = useState(true);

    const parentColumns = [
        {
            Header: 'S.No',
            accessor: 'id',
        },
        {
            Header: 'Staff',
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontWeight: 600 }}>{row.original.staffName}</div>
                        <div style={{ fontSize: 12, color: '#888' }}>{row.original.staffCode}</div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Total Km',
            accessor: 'totalKmSum',
        },
        {
            Header: 'Total Asked Amount',
            accessor: 'totalAmountSum',
        }
    ];

    const childColumns = [
        {
            Header: 'Date',
            accessor: 'allowanceDate',
            Cell: ({ value }) => dateConversion(value, 'DD/MM/YYYY')
        },
        {
            Header: 'From',
            accessor: 'fromPlace',
            Cell: ({ value }) => {
                return (
                    <div>
                        {Array.isArray(value)
                            ? value.map((item, index) => <div key={index}>{item}</div>)
                            : value?.split(/[\n,]+/).map((word, index) => <div key={index}>{word}</div>)
                        }
                    </div>
                );
            }
        },
        {
            Header: 'To',
            accessor: 'toPlace',
            Cell: ({ value }) => {
                return (
                    <div>
                        {Array.isArray(value)
                            ? value.map((item, index) => <div key={index}>{item}</div>)
                            : value?.split(/[\n,]+/).map((word, index) => <div key={index}>{word}</div>)
                        }
                    </div>
                );
            }
        },
        {
            Header: 'Activity',
            accessor: 'activityName',
        },
        {
            Header: 'Km',
            accessor: 'totalKm',
        },
        {
            Header: 'Asked Amount',
            accessor: 'totalAmount',
        },
        {
            Header: 'Image Status',
            accessor: 'isImageApproved',
            Cell: ({ row }) => {
                const statusMap = {
                    0: { text: 'Cancelled', color: 'danger' },
                    1: { text: 'Approved', color: 'success' },
                    2: {
                        text: row?.billImageName ? 'Pending' : 'Img not upload',
                        color: row?.billImageName ? 'warning' : 'primary'
                    }
                };
                const status = statusMap[row?.isImageApproved] || statusMap[2];
                return <Badge bg={status.color}>{status.text}</Badge>;
            }
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const hasImage = !!row?.billImageName;
                return (
                    <div>
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) && (
                            <span className="text-danger me-2 cursor-pointer" onClick={(e) => onEditForm(row)}>
                                <i className={'fe-file-text'}></i>
                            </span>
                        )}
                        <span className="text-success me-2 cursor-pointer" onClick={(e) => {
                            e.stopPropagation();
                            onPrintDesign(row)
                        }}>
                            <i className={'fe-printer'}></i>
                        </span>
                        {(roleIdforRole == 1 || _.includes(accessIds, '6') || _.includes(accessIds, '7')) && (
                            <span
                                className={`me-2 cursor-pointer ${hasImage ? 'text-primary' : 'text-secondary'}`}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleApproveImage(row.petrolAllowanceId, row.billImageName)
                                }}
                                title={hasImage ? 'Approve image' : 'No image to approve'}
                            >
                                <i className={'fe-check-circle'}></i>
                            </span>
                        )}
                    </div>
                );
            }
        }
    ];


    const [state, setState] = useState({
        dateOfPurchase: moment().format("YYYY-MM-DD"),
        fromDate: moment().startOf('isoWeek').format('YYYY-MM-DD'),
        toDate: moment().format('YYYY-MM-DD'),
        staffId: "",
        branchId: roleIdforRole != 1 ? branchIdforRole : 0,
        departmentId: 0,
    });

    const [optionListState, setOptionListState] = useState({
        departmentList: [
            { "departmentId": 0, "departmentName": "All" },
        ],
        branchList: [{ "branchId": 0, "branchName": "All" }],
    });

    const [selectedItem, setSelectedItem] = useState({});
    const [formContain, setFormContain] = useState(filterFormContainer);
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [isApproving, setIsApproving] = useState(false);
    const [isDispproving, setIsDispproving] = useState(false);
    const [parentList, setParentList] = useState([]);
    const [errors, setErrors] = useState([]);

    const errorHandle = useRef();

    useEffect(() => {
        setIsLoading(true);
        const req = {
            fromDate: state?.fromDate,
            toDate: state?.toDate,
            departmentId: state?.departmentId || '',
            branchId: state?.branchId || '',
        };

        dispatch(getPetrolAllowanceRequest(req));
        // dispatch(getStaffRequest(roleIdforRole != 1 && req));
        dispatch(getBranchRequest({ isActive: 1 }));
        dispatch(getDepartmentRequest({ isActive: 1 }));
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            const updatedFilterFormContainer = filterFormContainer.filter(container => {
                return !container.formFields.some(field => field.name === 'branchId');
            });
            setFormContain(updatedFilterFormContainer);
        }
    }, [filterFormContainer, roleIdforRole]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                branchList: [{
                    "branchId": 0,
                    "branchName": "All",
                }, ...getBranchList],
            });
            dispatch(resetGetBranch());
        } else if (getBranchFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                branchList: []
            });
            dispatch(resetGetBranch());
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                departmentList: [{
                    "departmentId": 0,
                    "departmentName": "All",
                }, ...getDepartmentList],
            });
            dispatch(resetGetDepartment());
        } else if (getDepartmentFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                departmentList: []
            });
            dispatch(resetGetDepartment());
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);

    useEffect(() => {
        if (getPetrolAllowanceReportSuccess) {
            setIsLoading(false);
            if (getPetrolAllowanceReportData?.length > 0) {
                navigate('/petrol-allowance-report', {
                    state: {
                        ...getPetrolAllowanceReportData[0],
                        month: state.toDate,
                        fromDate: state.fromDate,
                        toDate: state.toDate
                    }
                });
            }
            dispatch(resetGetPetrolAllowanceReport());
        } else if (getPetrolAllowanceReportFailure) {
            setIsLoading(false);
            dispatch(resetGetPetrolAllowanceReport());
        }
    }, [getPetrolAllowanceReportSuccess, getPetrolAllowanceReportFailure]);

    useEffect(() => {
        if (getPetrolAllowanceSuccess) {
            setIsLoading(false);

            const groupedData = _.values(
                _.groupBy(getPetrolAllowanceList, 'staffId')
            ).map((group, index) => {
                const staff = group[0];
                return {
                    id: index + 1,
                    staffId: staff.staffId,
                    staffName: staff.staffName,
                    staffCode: staff.staffCode,
                    staffProfile: staff.staffProfile,
                    totalKmSum: _.sumBy(group, (o) => Number(o.totalKm) || 0),
                    totalAmountSum: _.sumBy(group, (o) => Number(o.totalAmount) || 0),

                    children: group, // sub-rows
                };
            });
            setParentList(groupedData);
            dispatch(resetGetPetrolAllowance());
        } else if (getPetrolAllowanceFailure) {
            setIsLoading(false);
            setParentList([]);
            dispatch(resetGetPetrolAllowance());
        }
    }, [getPetrolAllowanceSuccess, getPetrolAllowanceFailure]);


    useEffect(() => {
        if (createUploadImagesSuccess) {
            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));
            dispatch(resetCreateUploadImages());
        } else if (createUploadImagesFailure) {
            dispatch(resetCreateUploadImages());
        }
    }, [createUploadImagesSuccess, createUploadImagesFailure]);

    useEffect(() => {
        if (createPetrolAllowanceSuccess) {
            try {
                if (state.billImageName?.length > 0) {
                    const formData = new FormData();
                    const originalFile = state.billImageName[0];
                    const renamedFile = new File(
                        [originalFile],
                        `petrol-allowance-${createPetrolAllowanceData[0]?.petrolAllowanceId}-${createPetrolAllowanceData[0]?.staffCode}-${originalFile.name}`,
                        {
                            type: originalFile.type,
                            lastModified: originalFile.lastModified,
                        }
                    );
                    formData.append('petrolAllowanceProof', renamedFile);
                    dispatch(createUploadImagesRequest(formData, createPetrolAllowanceData[0]?.petrolAllowanceId));
                }
            } catch (error) {
                console.log(error);
            }

            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));

            showMessage('success', 'Created Successfully');
            closeModel();
            dispatch(resetCreatePetrolAllowance());
        } else if (createPetrolAllowanceFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreatePetrolAllowance());
        }
    }, [createPetrolAllowanceSuccess, createPetrolAllowanceFailure]);

    useEffect(() => {
        if (createPetrolAllowanceSuccess || updatePetrolAllowanceSuccess) {
            const data = createPetrolAllowanceSuccess ? createPetrolAllowanceData : updatePetrolAllowanceData;

            try {
                if (state.billImageName?.length > 0) {
                    const formData = new FormData();
                    const originalFile = state.billImageName[0];
                    const renamedFile = new File(
                        [originalFile],
                        `petrol-allowance-${data[0]?.petrolAllowanceId}-${data[0]?.staffCode}-${originalFile.name}`,
                        {
                            type: originalFile.type,
                            lastModified: originalFile.lastModified,
                        }
                    );
                    formData.append('petrolAllowanceProof', renamedFile);
                    dispatch(createUploadImagesRequest(formData, data[0]?.petrolAllowanceId));
                }
            } catch (error) {
                console.log(error);
            }

            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));

            showMessage('success', createPetrolAllowanceSuccess ? 'Created Successfully' : 'Updated Successfully');
            closeModel();
            dispatch(createPetrolAllowanceSuccess ? resetCreatePetrolAllowance() : resetUpdatePetrolAllowance());
        }
    }, [createPetrolAllowanceSuccess, updatePetrolAllowanceSuccess]);

    useEffect(() => {
        if (updatePetrolAllowanceSuccess) {
            const temp_state = [...parentList];
            temp_state[selectedIndex] = updatePetrolAllowanceData[0];
            try {
                if (state.billImageName?.length > 0) {
                    const formData = new FormData();
                    const originalFile = state.billImageName[0];
                    const renamedFile = new File(
                        [originalFile],
                        `petrol-allowance-${updatePetrolAllowanceData[0]?.petrolAllowanceId}-${updatePetrolAllowanceData[0]?.staffCode}-${originalFile.name}`,
                        {
                            type: originalFile.type,
                            lastModified: originalFile.lastModified,
                        }
                    );
                    formData.append('petrolAllowanceProof', renamedFile);
                    dispatch(createUploadImagesRequest(formData, updatePetrolAllowanceData[0]?.petrolAllowanceId));
                }
            } catch (error) {
                console.log(error);
            }
            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));
            isEdit && showMessage('success', 'Allowance Successfully Updated');
            closeModel();
            dispatch(resetUpdatePetrolAllowance());
        } else if (updatePetrolAllowanceFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdatePetrolAllowance());
        }
    }, [updatePetrolAllowanceSuccess, updatePetrolAllowanceFailure]);

    useEffect(() => {
        if (approvePetrolAllowanceImageSuccess) {
            setIsApproving(false);
            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));

            showMessage('success', 'Image approved successfully!');
            dispatch(resetApprovePetrolAllowanceImage());
        } else if (approvePetrolAllowanceImageFailure) {
            setIsApproving(false);
            showMessage('error', errorMessage || 'Failed to approve image');
            dispatch(resetApprovePetrolAllowanceImage());
        }
    }, [approvePetrolAllowanceImageSuccess, approvePetrolAllowanceImageFailure]);

    useEffect(() => {
        if (disapprovePetrolAllowanceImageSuccess) {
            setIsDispproving(false);
            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));
            showMessage('success', 'Image disapproved successfully!');
            dispatch(resetDisapprovePetrolAllowanceImage());
        } else if (disapprovePetrolAllowanceImageFailure) {
            setIsDispproving(false);
            showMessage('error', errorMessage || 'Failed to disapprove image');
            dispatch(resetDisapprovePetrolAllowanceImage());
        }
    }, [disapprovePetrolAllowanceImageSuccess, disapprovePetrolAllowanceImageFailure]);

    const closeModel = () => {
        isEdit = false;
        onFormClear();
        setModal(false);
    };

    const onPrintDesign = (data) => {
        const reqReport = {
            staffId: data?.staffId,
            fromDate: state?.fromDate,
            toDate: state?.toDate,
        };
        dispatch(getPetrolAllowanceReportRequest(reqReport));
    };

    const onStatusForm = (data, index, activeChecker) => {
        const submitRequest = {
            statusId: activeChecker,
        };
        setSelectedIndex(index);
        dispatch(updatePetrolAllowanceRequest(submitRequest, data.petrolAllowanceId));
    };

    const onFormClear = () => {
        setState({
            ...state,
            dateOfPurchase: moment().format("YYYY-MM-DD"),
            fromDate: state?.fromDate ? state?.fromDate : moment().startOf('isoWeek').format('YYYY-MM-DD'),
            toDate: state?.toDate ? state?.toDate : moment().format('YYYY-MM-DD'),
            staffId: "",
            totalKm: "",
            totalAmount: "",
            billNo: "",
            nameOfDealer: "",
            qtyPerLitre: "",
            pricePerLitre: "",
            dateOfPurchase: "",
        });
    };


    const handleApproveImage = (petrolAllowanceId, billImageName, index) => {
        if (!billImageName) {
            showMessage('warning', 'Please upload image first');
            return; // This will exit the function and prevent the dialog from opening
        }

        // Only proceed if there is an image
        setCurrentImageUrl(`${baseURL}${billImageName}`);
        setCurrentPetrolId(petrolAllowanceId);
        setCurrentRowIndex(index);
        setShowImageDialog(true);
        setImageLoading(true);
    };

    useEffect(() => {
        if (!showImageDialog) {
            setCurrentImageUrl('');
            setCurrentPetrolId(null);
            setCurrentRowIndex(null);
            setImageLoading(true);
        }
    }, [showImageDialog]);

    useEffect(() => {
        if (approvePetrolAllowanceImageSuccess) {
            setIsApproving(false);
            const req = {
                fromDate: state?.fromDate,
                toDate: state?.toDate,
                departmentId: state?.departmentId || '',
                branchId: state?.branchId || '',
            };
            dispatch(getPetrolAllowanceRequest(req));
            dispatch(resetApprovePetrolAllowanceImage());
        } else if (approvePetrolAllowanceImageFailure) {
            setIsApproving(false);
            dispatch(resetApprovePetrolAllowanceImage());
        }
    }, [approvePetrolAllowanceImageSuccess, approvePetrolAllowanceImageFailure]);



    const createModel = () => {
        onFormClear();
        isEdit = false;
        setModal(true);
    };

    const onEditForm = (data, index) => {
        setState({
            ...state,
            staffId: data?.staffId || "",
            totalKm: data?.totalKm || "",
            totalAmount: data?.totalAmount || "",
            billNo: data?.billNo || "",
            nameOfDealer: data?.nameOfDealer || "",
            qtyPerLitre: data?.qtyPerLitre || "",
            pricePerLitre: data?.pricePerLitre || "",
            dateOfPurchase: data?.dateOfPurchase || moment().format("YYYY-MM-DD"),
        });
        setSelectedItem(data);
        setSelectedIndex(index);
        setModal(true);
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    };

    const onFormSubmit = async () => {
        const submitRequest = {
            billNo: state?.billNo || "",
            dateOfPurchase: state?.dateOfPurchase || "",
            nameOfDealer: state?.nameOfDealer || "",
            pricePerLitre: state?.pricePerLitre || "",
            qtyPerLitre: state?.qtyPerLitre || "",
            totalAmount: state?.totalAmount || "",
        };
        dispatch(updatePetrolAllowanceRequest(submitRequest, selectedItem.petrolAllowanceId));
    };

    const searchFilter = () => {
        // const filteredDate = !isNaN(Date.parse(state.dateFilter)) ? dateConversion(state.dateFilter, "YYYY-MM-DD") : null
        // if (isNaN(Date.parse(filteredDate)) && state.staffId === "") {
        //     showMessage('warning', 'Please Select Given Option...!')
        // } else {
        //     const searchReq = {
        //         isActive: 1,
        //         dateFilter: filteredDate,
        //         staffId: state?.staffId || null,
        //     }
        //     const filterGetObj = removeNullKeyFromObj(searchReq)
        //     dispatch(getPetrolAllowanceRequest(filterGetObj));
        // }
    }

    const onFromDate = (event, name) => {
        setState({
            ...state,
            [name]: event.target.value
        });
        const searchReq = {
            fromDate: event.target.value,
            toDate: state?.toDate,
            branchId: state?.branchId || '',
            departmentId: state?.departmentId || ''
        };
        dispatch(getPetrolAllowanceRequest(searchReq));
    };

    const onToDate = (event, name) => {
        setState({
            ...state,
            [name]: event.target.value
        });
        const searchReq = {
            toDate: event.target.value,
            fromDate: state?.fromDate,
            branchId: state?.branchId || '',
            departmentId: state?.departmentId || ''
        };
        dispatch(getPetrolAllowanceRequest(searchReq));
    };

    const handleBranch = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            branchId: option[uniqueKey] || '',
            departmentId: state?.departmentId || '',
            fromDate: state?.fromDate,
            toDate: state?.toDate
        };
        dispatch(getPetrolAllowanceRequest(filterBranch));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        });
    };

    const handleDepartment = (option, formName, uniqueKey, displayKey) => {
        const filterDepartment = {
            departmentId: option[uniqueKey] || '',
            branchId: state?.branchId || branchIdforRole,
            fromDate: state?.fromDate,
            toDate: state?.toDate
        };
        dispatch(getPetrolAllowanceRequest(filterDepartment));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        })
    }

    // const onHandleCameraCapture = () => {
    //     alert("Hello world")
    // }

    const groupedData = _.values(
        _.groupBy(parentList, 'staffId')
    ).map((group, index) => {
        const staff = group[0];
        return {
            id: index + 1,
            staffId: staff.staffId,
            staffName: staff.staffName,
            staffCode: staff.staffCode,
            staffProfile: staff.staffProfile,
            totalKm: _.sumBy(group, (o) => Number(o.totalKm) || 0),
            totalAmount: _.sumBy(group, (o) => Number(o.totalAmount) || 0),

            children: group, // sub-rows
        };
    });

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? (
                <div className='bg-light opacity-0.25'>
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className='mt-5 mb-5' animation="border" />
                    </div>
                </div>
            ) : (
                // <Table
                //     columns={parentColumns}
                //     childColumns={childColumns}
                //     Title={'Petrol Allowance List'}
                //     data={groupedData || []}
                //     pageSize={25}
                //     filterTbl={true}
                //     filterFormContainer={formContain}
                //     filterSubmitFunction={searchFilter}
                //     filterColNo={4}
                //     setState={setState}
                //     state={state}
                //     // onClickCallBack={{ "searchFilter": searchFilter }}
                //     onChangeCallBack={{
                //         "onFromDate": onFromDate,
                //         "onToDate": onToDate,
                //         "handleDepartment": handleDepartment,
                //         "handleBranch": handleBranch
                //     }}
                //     optionListState={optionListState}
                // />

                <Table
                    columns={parentColumns}
                    childColumns={childColumns}
                    Title="Petrol Allowance List"
                    data={parentList || []}
                    pageSize={25}
                    filterTbl={true}
                    filterFormContainer={formContain}
                    filterSubmitFunction={searchFilter}
                    filterColNo={4}
                    setState={setState}
                    state={state}
                    isExpandable={true}
                    onChangeCallBack={{
                        onFromDate,
                        onToDate,
                        handleDepartment,
                        handleBranch,
                    }}
                    optionListState={optionListState}
                />

            )}
            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={'Allowance'}
                modelSize={'md'}
                isEdit={isEdit}
                modelHead={'true'}
                handleSubmit={handleValidation}
            >
                <FormLayout
                    dynamicForm={petrolAllowanceContainer}
                    handleSubmit={onFormSubmit}
                    setState={setState}
                    state={state}
                    ref={errorHandle}
                    noOfColumns={1}
                    errors={errors}
                    setErrors={setErrors}
                />
            </ModelViewBox>

            <Modal show={showImageDialog} onHide={() => setShowImageDialog(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Bill Image Approval</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <div style={{ textAlign: 'center', margin: '10px 0', minHeight: '200px' }}>
                        {imageLoading && (
                            <div style={{
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                height: '200px'
                            }}>
                                <Spinner animation="border" />
                            </div>
                        )}
                        <img
                            src={currentImageUrl}
                            alt="Bill"
                            data-fallback={ImageNotFound}
                            style={{
                                maxWidth: '100%',
                                maxHeight: '300px',
                                display: imageLoading ? 'none' : 'block',
                                margin: '0 auto',
                                border: '1px solid #ddd'
                            }}
                            className="js-fallback-img"
                            crossOrigin="anonymous"
                            onLoad={() => setImageLoading(false)}
                            onError={(e) => {
                                setImageLoading(false);
                                e.target.src = e.target.dataset.fallback;
                            }}
                        />
                    </div>
                </Modal.Body>
                <Modal.Footer>
                    {(roleIdforRole == 1 || _.includes(accessIds, '7')) && (
                        <Button
                            variant="danger"
                            onClick={() => {
                                setIsDispproving(true);
                                dispatch(disapprovePetrolAllowanceImageRequest(currentPetrolId));
                                setSelectedIndex(currentRowIndex);
                                setShowImageDialog(false);
                            }}
                            disabled={isApproving || isDispproving}
                        >
                            {isDispproving ? (
                                <>
                                    <Spinner as="span" size="sm" animation="border" />
                                    <span className="ms-2">Disapproving...</span>
                                </>
                            ) : 'Disapprove'}
                        </Button>
                    )}
                    {(roleIdforRole == 1 || _.includes(accessIds, '6')) && (
                        <Button
                            variant="success"
                            onClick={() => {
                                setIsApproving(true);
                                dispatch(approvePetrolAllowanceImageRequest(currentPetrolId));
                                setSelectedIndex(currentRowIndex);
                                setShowImageDialog(false);
                            }}
                            disabled={isApproving || isDispproving}
                        >
                            {isApproving ? (
                                <>
                                    <Spinner as="span" size="sm" animation="border" />
                                    <span className="ms-2">Approving...</span>
                                </>
                            ) : 'Approve'}
                        </Button>
                    )}
                </Modal.Footer>
            </Modal>
        </React.Fragment>
    );
}

export default Index;